const TZ = 'Asia/Karachi';
const body = $json.body || $json;
const msg = body.message || {};
const call = msg.call || {};
const callId = call.id || ('unknown-' + Date.now());   // never blank: a blank id could match an empty row
const hasRealCallId = !!call.id;
const customerNumber = (call.customer && call.customer.number) || (msg.customer && msg.customer.number) || '';
const customerName = (call.customer && call.customer.name) || (msg.customer && msg.customer.name) || '';
const endedReason = msg.endedReason || call.endedReason || '';
const transcript = String((msg.artifact && msg.artifact.transcript) || msg.transcript || '').slice(0, 20000);

// Lines spoken by the lead only (used for the opt-out safety net)
const userLines = transcript.split('\n').filter(l => /^\s*(user|customer)\s*:/i.test(l));
const userText = userLines.join('\n');

const NO_ANSWER = /(did-not-answer|busy|voicemail|no-answer)/i;
const FAILED = /(error|failed|not-found|invalid|unauthorized)/i;

let route = 'llm', error = '';
if (!hasRealCallId) { route = 'error'; error = 'Webhook payload has no call id'; }
else if (NO_ANSWER.test(endedReason)) route = 'no_answer';
else if (FAILED.test(endedReason)) { route = 'error'; error = 'Call failed: ' + endedReason; }
else if (!transcript.trim()) { route = 'error'; error = 'Transcript missing (ended: ' + endedReason + ')'; }
else if (userLines.length === 0) route = 'no_answer';

const nowLocal = new Date().toLocaleString('en-GB', { timeZone: TZ, hour12: false });

const system = `You extract structured data from a phone-call transcript between an AI sales assistant ("AI") and a lead ("User") for Logicfast, an AI automation company. The call may be in English, Urdu, Roman Urdu, or a mix.

Return JSON with these fields:
- outcome: one of "interested", "not_interested", "callback", "opt_out", "no_answer".
  * interested: the lead wants more info, a demo, a meeting, or agrees that the Logicfast team may contact them.
  * not_interested: the lead declines but does NOT forbid future calls.
  * callback: the lead is busy or asks to be called at another time.
  * opt_out: the lead asks not to be called again, to be removed from the list, or to stop calls, in ANY wording or language (for example "dobara call mat karna", "remove my number", "stop calling me").
  * no_answer: the lead never meaningfully spoke (silence, voicemail, hang-up with no content).
- contact_name: the lead's own name if they said it during the call (for example when the AI asked "Aap ka naam kya hai?"), otherwise null. Write it in Latin letters (transliterate from Urdu).
- contact_phone: a phone number the lead gave during the call, converted to digits (Pakistani numbers as +92XXXXXXXXXX), otherwise null.
- callback_time: ISO 8601 with +05:00 offset, resolved against the current date/time given below, if the lead named a time to be called back. Otherwise null. If the time is vague (for example "later"), use null.
- summary: ONE line in English, maximum 25 words.
- unanswered_questions: array of questions the lead asked that the AI could not answer or deferred to the team. Empty array if none.
- opt_out: true if the lead asked not to be called again, otherwise false.

Rules:
- Use only what is in the transcript. Never invent facts.
- Priority if several apply: opt_out, then callback, then interested, then not_interested.
- If outcome is "opt_out", opt_out must be true.
- "Not now, call me tomorrow" is callback, not opt_out.`;

const userMsg = `Current date/time (Pakistan, Asia/Karachi): ${nowLocal}\n\nTRANSCRIPT:\n${transcript}`;

const schema = {
  type: 'OBJECT',
  properties: {
    outcome: { type: 'STRING', enum: ['interested', 'not_interested', 'callback', 'opt_out', 'no_answer'] },
    callback_time: { type: 'STRING', nullable: true },
    summary: { type: 'STRING' },
    unanswered_questions: { type: 'ARRAY', items: { type: 'STRING' } },
    opt_out: { type: 'BOOLEAN' },
    contact_name: { type: 'STRING', nullable: true },
    contact_phone: { type: 'STRING', nullable: true },
  },
  required: ['outcome', 'callback_time', 'summary', 'unanswered_questions', 'opt_out', 'contact_name', 'contact_phone'],
};

const llmBody = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: userMsg }] }],
  generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: schema },
};

return [{ json: { callId, endedReason, transcript, userText, route, error, customerName, customerNumber, llmBody } }];

const r = $json;
const na = r.route === 'no_answer';
return [{ json: {
  call_id: r.callId,
  name: r.customerName || '',
  number: r.customerNumber || '',
  status: na ? 'no_answer' : 'error',
  outcome: na ? 'no_answer' : '',
  callback_time: '',
  summary: na ? ('No answer (' + (r.endedReason || 'no speech') + ')') : '',
  unanswered_questions: '',
  do_not_call: '',
  error: na ? '' : r.error,
}}];

const p = $('Parse Report1').item.json;
const fail = msg => [{ json: {
  call_id: p.callId, name: p.customerName || '', number: p.customerNumber || '', status: 'error', outcome: '', callback_time: '',
  summary: '', unanswered_questions: '', do_not_call: '', error: msg,
}}];

let data;
try {
  const text = $json.candidates[0].content.parts.map(x => x.text || '').join('');
  data = JSON.parse(text.replace(/```json|```/g, '').trim());
} catch (e) {
  return fail('LLM output was not valid JSON: ' + e.message);
}

const OUTCOMES = ['interested', 'not_interested', 'callback', 'opt_out', 'no_answer'];
if (!OUTCOMES.includes(data.outcome)) return fail('LLM returned invalid outcome: ' + data.outcome);

// Opt-out safety net: even if the LLM misses it, phrases spoken by the LEAD force do-not-call
const OPT = /(do not call (me )?again|don'?t call (me )?again|stop calling|remove (me|my number)|take me off|unsubscribe|do?bara (call|phone) (mat|na)|dubara (call|phone) (mat|na))/i;
const optOut = data.opt_out === true || data.outcome === 'opt_out' || OPT.test(p.userText || '');

// Name/number: use what the call carried (n8n-started calls); fall back to what the lead said (web/test calls)
const cleanPhone = String(data.contact_phone || '').replace(/[^\d+]/g, '');
return [{ json: {
  call_id: p.callId,
  name: p.customerName || data.contact_name || '',
  number: p.customerNumber || cleanPhone || '',
  status: optOut ? 'do_not_call' : data.outcome,
  outcome: optOut ? 'opt_out' : data.outcome,
  callback_time: optOut ? '' : (data.callback_time || ''),
  summary: data.summary || '',
  unanswered_questions: Array.isArray(data.unanswered_questions) ? data.unanswered_questions.join(' | ') : '',
  do_not_call: optOut ? 'TRUE' : '',
  error: '',
}}];

const p = $('Parse Report1').item.json;
const e = $json.error;
const detail = (e && (e.message || JSON.stringify(e))) || JSON.stringify($json);
return [{ json: {
  call_id: p.callId, name: p.customerName || '', number: p.customerNumber || '', status: 'error', outcome: '', callback_time: '',
  summary: '', unanswered_questions: '', do_not_call: '',
  error: ('LLM extraction failed: ' + detail).slice(0, 300),
}}];
